class Solution {
    vector<vector<int>> adj;
    vector<int> xorSub, tin, tout, vals;
    int timer;

    void dfs(int u, int p) {
        tin[u] = timer++;
        xorSub[u] = vals[u];
        for (int v : adj[u]) {
            if (v != p) {
                dfs(v, u);
                xorSub[u] ^= xorSub[v];
            }
        }
        tout[u] = timer++;
    }

public:
    int minimumScore(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        adj.assign(n, {});
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        xorSub.assign(n, 0);
        tin.assign(n, 0);
        tout.assign(n, 0);
        vals = nums;
        timer = 0;
        dfs(0, -1);
        int total = xorSub[0];

        auto isAnc = [&](int a, int b) -> bool {
            return tin[a] <= tin[b] && tout[b] <= tout[a];
        };

        int ans = INT_MAX;
        for (int u = 1; u < n; u++) {
            for (int v = u + 1; v < n; v++) {
                int a, b, c;
                if (isAnc(u, v)) {
                    a = xorSub[v];
                    b = xorSub[u] ^ xorSub[v];
                    c = total ^ xorSub[u];
                } else if (isAnc(v, u)) {
                    a = xorSub[u];
                    b = xorSub[v] ^ xorSub[u];
                    c = total ^ xorSub[v];
                } else {
                    a = xorSub[u];
                    b = xorSub[v];
                    c = total ^ xorSub[u] ^ xorSub[v];
                }
                int mx = max({a, b, c});
                int mn = min({a, b, c});
                ans = min(ans, mx - mn);
            }
        }
        return ans;
    }
};
